// OctaPassVault for the native Android app (plan 17): the Kotlin bindings (src/main/kotlin,
// generated by crates/octapass-mobile/scripts/build-android.sh) over liboctapass_mobile.so
// (jniLibs/), plus src/android/kotlin (Android-only glue). The phase-2 app module adds both
// source folders and jniLibs, with `net.java.dev.jna:jna:<version>@aar` instead of the plain
// JNA jar.
//
// The tests run on the JVM against a host build of the library and the real sync server:
// crates/octapass-mobile/scripts/test-kotlin.sh passes the library's folder as
// -PoctapassVaultLibrary=<dir> and the server as OCTAPASS_TEST_SERVER.
plugins {
    kotlin("jvm") version "2.3.20"
}

group = "app.octap"
version = "0.1.0"

val library: String? = providers.gradleProperty("octapassVaultLibrary").orNull

kotlin {
    jvmToolchain(17)
}

dependencies {
    implementation("net.java.dev.jna:jna:5.19.1")
    // The bindings' async calls are suspend functions.
    implementation("org.jetbrains.kotlinx:kotlinx-coroutines-core:1.10.2")
    testImplementation(kotlin("test"))
}

tasks.test {
    useJUnitPlatform()
    onlyIf("needs a host build of the library (scripts/test-kotlin.sh)") { library != null }
    systemProperty("jna.library.path", library ?: "")
    environment("OCTAPASS_TEST_SERVER", System.getenv("OCTAPASS_TEST_SERVER") ?: "http://127.0.0.1:8080")
    testLogging { events("passed", "failed") }
}
